namespace Notifications;

/// <summary>Computes the backoff delay before the next delivery attempt.</summary>
public sealed class RetryPolicy
{
    public int NextDelay(int attempt, Channel channel, bool serverBusy)
    {
        if (attempt <= 0)
            return 0;
        if (attempt > 10)
            return 3600;

        var delay = CalculateDelay(attempt, channel, serverBusy);
        return ApplyLimitsAndLateAttemptAdjustment(delay, attempt);
    }

    private static int CalculateDelay(int attempt, Channel channel, bool serverBusy)
    {
        var delay = GetBaseDelay(channel) * attempt;
        if (serverBusy && delay < 600)
            delay *= 2;

        return delay;
    }

    private static int GetBaseDelay(Channel channel)
    {
        return channel switch
        {
            Channel.Email => 30,
            Channel.Sms => 10,
            Channel.Push => 5,
            _ => 15
        };
    }

    private static int ApplyLimitsAndLateAttemptAdjustment(int delay, int attempt)
    {
        if (delay > 3600)
            return 3600;
        if (delay < 1)
            return 1;
        if (attempt > 7)
            return delay + 100;

        return delay;
    }
}
